#include "bits/stdc++.h"

#define rep(i, n) for(int i = 0; i < (n); ++i)
#define all(a) (a).begin(), (a).end()

using namespace std;

using ll = long long;
using vl = vector<ll>;
using vi = vector<int>;
const int INFi  = 2e9;

void solve() {
    int n; ll k; cin >> n >> k;
    vector<pair<ll, ll>> a(n);
    rep(i, n) cin >> a[i].first;
    rep(i, n) cin >> a[i].second;
    rep(i, n) {
        if (a[i].first < a[i].second) swap(a[i].first, a[i].second);
    }
    sort(all(a));
    vector<ll> px(n + 1);
    rep(i, n) px[i + 1] = px[i] + a[i].second;
    vector<ll> pxy(n + 1);
    rep(i, n) pxy[i + 1] = pxy[i] + a[i].first * a[i].second;

    int ban = -1;

    auto GetSumX = [&] (int l, int r) {
        if (l >= r) return 0ll;
        ll s = px[r] - px[l];
        if (l <= ban && ban < r) s -= a[ban].second;
        return s;
    };

    auto GetSumXY = [&] (int l, int r) {
        if (l >= r) return 0ll;
        ll s = pxy[r] - pxy[l];
        if (l <= ban && ban < r) s -= a[ban].second * a[ban].first;
        return s;
    };


    ll ANS = 8e18;
    rep(i, n) {
        auto [y, x] = a[i];
        ban = i;
        y += k;

        int pos = lower_bound(all(a), make_pair(y, -1)) - a.begin();

        // [pos, n) -> done

        int l = pos - 1;
        int r = n;
        while (r - l > 1) {
            int m = (l + r) / 2;
            if (GetSumX(m, n) <= k) {
                r = m;
            } else {
                l = m;
            }
        }

        ll kx = k;
        kx -= GetSumX(r, n);

        ll ans = 0;
        if (pos <= l) {
            ans = GetSumXY(0, l) + y * x + a[l].first * (a[l].second - kx);
            ANS = min(ANS, ans);
            continue;
        }

        {
            ll t = min(kx, x);
            kx -= t;
            x -= t;
            ans += x * y;
        }

        l = -1;
        r = pos;

        while (r - l > 1) {
            int m = (l + r) / 2;
            if (GetSumX(m, pos) <= kx) {
                r = m;
            } else {
                l = m;
            }
        }

        kx -= GetSumX(r, pos);

        if (0 <= l) {
            ans += a[l].first * (a[l].second - kx);
            ans += GetSumXY(0, l);
        }
        ANS = min(ANS, ans);
    }

    cout << ANS << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
